16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "postcode")
60	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
61	    private String postcode;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @Column(name = "household_size")
76	    private Integer householdSize;
77	
78	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
79	    private Set<Pet> pets;
80	
81	    /** Common street-type abbreviations expanded during address normalization. */
82	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
83	        "ST", "STREET",
84	        "RD", "ROAD",
85	        "AVE", "AVENUE");
86	
87	    /** Fixed city-to-region table used to derive an owner's locality. */
88	    private static final Map<String, String> CITY_REGION = Map.of(
89	        "Sydney", "NSW",
90	        "Melbourne", "VIC",
91	        "Brisbane", "QLD");
92	
93	    /** Fixed region-to-postcode-range table (inclusive) used to validate a postcode. */
94	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
95	        "NSW", new int[] {2000, 2099},
96	        "VIC", new int[] {3000, 3099},
97	        "QLD", new int[] {4000, 4099});
98	
99	    public String getAddress() {
100	        return this.address;
101	    }
102	
103	    /**
104	     * Set the owner's address, normalizing it to a canonical form so it is both
105	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
106	     * internal runs of whitespace are collapsed to a single space, the value is
107	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
108	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
109	     * left as-is.
110	     */
111	    public void setAddress(String address) {
112	        this.address = normalizeAddress(address);
113	    }
114	
115	    /**
116	     * Normalize an address string to its canonical form: trimmed, whitespace
117	     * collapsed, upper-cased, with common street-type abbreviations expanded.
118	     * Returns {@code null} for a {@code null} input; a value that is blank once
119	     * trimmed normalizes to the empty string.
120	     */
121	    public static String normalizeAddress(String address) {
122	        if (address == null) {
123	            return null;
124	        }
125	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
126	        if (collapsed.isEmpty()) {
127	            return "";
128	        }
129	        String[] tokens = collapsed.split(" ");
130	        StringBuilder sb = new StringBuilder();
131	        for (int i = 0; i < tokens.length; i++) {
132	            if (i > 0) {
133	                sb.append(' ');
134	            }
135	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
136	        }
137	        return sb.toString();
138	    }
139	
140	    public String getCity() {
141	        return this.city;
142	    }
143	
144	    public void setCity(String city) {
145	        this.city = city;
146	    }
147	
148	    public String getTelephone() {
149	        return this.telephone;
150	    }
151	
152	    public void setTelephone(String telephone) {
153	        this.telephone = telephone;
154	    }
155	
156	    public String getEmail() {
157	        return this.email;
158	    }
159	
160	    /**
161	     * Set the owner's email address, normalizing it to lower case so it is both
162	     * stored and returned in a canonical form. A {@code null} value is left as-is.
163	     */
164	    public void setEmail(String email) {
165	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
166	    }
167	
168	    public LocalDate getRegistrationDate() {
169	        return this.registrationDate;
170	    }
171	
172	    public void setRegistrationDate(LocalDate registrationDate) {
173	        this.registrationDate = registrationDate;
174	    }
175	
176	    public String getPostcode() {
177	        return this.postcode;
178	    }
179	
180	    public void setPostcode(String postcode) {
181	        this.postcode = postcode;
182	    }
183	
184	    /**
185	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
186	     * is always valid (postcode is optional). When present, a postcode is valid if
187	     * the city has no known region, or if it is four digits falling within the
188	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
189	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
190	     */
191	    public boolean isPostcodeValidForCity() {
192	        if (this.postcode == null) {
193	            return true;
194	        }
195	        String region = CITY_REGION.get(this.city);
196	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
197	        if (range == null) {
198	            return true;
199	        }
200	        if (!this.postcode.matches("^[0-9]{4}$")) {
201	            return false;
202	        }
203	        int value = Integer.parseInt(this.postcode);
204	        return value >= range[0] && value <= range[1];
205	    }
206	
207	    public String getCustomerCode() {
208	        return this.customerCode;
209	    }
210	
211	    public void setCustomerCode(String customerCode) {
212	        this.customerCode = customerCode;
213	    }
214	
215	    /**
216	     * Return a single Luhn check digit (0-9) computed over the digits contained in
217	     * the owner's customer code, or {@code null} when the customer code is not set.
218	     * Non-digit characters in the code are ignored; the rightmost digit is doubled
219	     * first, following the standard Luhn algorithm.
220	     */
221	    public Integer getCheckDigit() {
222	        if (this.customerCode == null) {
223	            return null;
224	        }
225	        int sum = 0;
226	        boolean doubleDigit = true;
227	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
228	            char c = this.customerCode.charAt(i);
229	            if (c < '0' || c > '9') {
230	                continue;
231	            }
232	            int digit = c - '0';
233	            if (doubleDigit) {
234	                digit *= 2;
235	                if (digit > 9) {
236	                    digit -= 9;
237	                }
238	            }
239	            sum += digit;
240	            doubleDigit = !doubleDigit;
241	        }
242	        return (10 - (sum % 10)) % 10;
243	    }
244	
245	    /**
246	     * Return the owner's membership number, formatted {@code '<customerCode>-M<YY>'}
247	     * where {@code YY} is the last two digits of the registration date's year (for
248	     * example {@code 'SMI-0007-M26'}). Returns {@code null} when either the customer
249	     * code or the registration date is not set.
250	     */
251	    public String getMembershipNumber() {
252	        if (this.customerCode == null || this.registrationDate == null) {
253	            return null;
254	        }
255	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
256	    }
257	
258	    public String getHouseholdId() {
259	        return this.householdId;
260	    }
261	
262	    public void setHouseholdId(String householdId) {
263	        this.householdId = householdId;
264	    }
265	
266	    public Integer getNamesakeCount() {
267	        return this.namesakeCount;
268	    }
269	
270	    /**
271	     * Return the owner's membership level, a number from {@code 1} to {@code 3}
272	     * assigned at creation: starting at {@code 1}, plus {@code 1} when an email
273	     * address is present, plus {@code 1} when the owner has no namesakes (namesake
274	     * count is {@code 0}), capped at {@code 3}. (Level {@code 4} is reserved for
275	     * tenure.)
276	     */
277	    public Integer getMembershipLevel() {
278	        int level = 1;
279	        boolean hasEmail = this.email != null && !this.email.isBlank();
280	        if (hasEmail) {
281	            level += 1;
282	        }
283	        if (this.namesakeCount != null && this.namesakeCount == 0) {
284	            level += 1;
285	        }
286	        return Math.min(level, 3);
287	    }
288	
289	    public void setNamesakeCount(Integer namesakeCount) {
290	        this.namesakeCount = namesakeCount;
291	    }
292	
293	    public Integer getHouseholdSize() {
294	        return this.householdSize;
295	    }
296	
297	    public void setHouseholdSize(Integer householdSize) {
298	        this.householdSize = householdSize;
299	    }
300	
301	    /**
302	     * Whether more than 80 owners had already been registered on this owner's
303	     * registration day at the time it was created, flagging a bulk-signup surge.
304	     */
305	    public Boolean getBulkSignupWarning() {
306	        return this.bulkSignupWarning;
307	    }
308	
309	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
310	        this.bulkSignupWarning = bulkSignupWarning;
311	    }
312	
313	    /**
314	     * Return the owner's locality (region), preferring the postcode: when the
315	     * postcode is present and falls within a known region's inclusive range
316	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
317	     * region is returned. Otherwise the value falls back to the fixed
318	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
319	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
320	     * table. This yields the same region for known cities but disambiguates
321	     * cities that share a name.
322	     */
323	    public String getLocality() {
324	        String regionFromPostcode = regionForPostcode();
325	        if (regionFromPostcode != null) {
326	            return regionFromPostcode;
327	        }
328	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
329	    }
330	
331	    /**
332	     * Look up the region whose inclusive postcode range contains this owner's
333	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
334	     * known range.
335	     */
336	    private String regionForPostcode() {
337	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
338	            return null;
339	        }
340	        int value = Integer.parseInt(this.postcode);
341	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
342	            int[] range = entry.getValue();
343	            if (value >= range[0] && value <= range[1]) {
344	                return entry.getKey();
345	            }
346	        }
347	        return null;
348	    }
349	
350	    /**
351	     * Return the owner's preferred contact channel, derived from the stored
352	     * contact details: {@code 'EMAIL'} when an email address is present,
353	     * otherwise {@code 'PHONE'}.
354	     */
355	    public String getContactPreference() {
356	        boolean hasEmail = this.email != null && !this.email.isBlank();
357	        return hasEmail ? "EMAIL" : "PHONE";
358	    }
359	
360	    /**
361	     * Return the owner's derived identity key, which consolidates all duplicate
362	     * detection into a single value formed as
363	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}.
364	     * The telephone and email are already stored in their normalized (E.164 /
365	     * lower-cased) forms; a missing email or household id contributes an empty
366	     * segment. A create is rejected only when a new owner's whole identity key
367	     * equals an existing owner's.
368	     */
369	    public String getIdentityKey() {
370	        String telephonePart = this.telephone == null ? "" : this.telephone;
371	        String emailPart = (this.email == null) ? "" : this.email;
372	        String householdPart = (this.householdId == null) ? "" : this.householdId;
373	        return telephonePart + "|" + emailPart + "|" + householdPart;
374	    }
375	
376	    protected Set<Pet> getPetsInternal() {
377	        if (this.pets == null) {
378	            this.pets = new HashSet<>();
379	        }
380	        return this.pets;
381	    }
382	
383	    protected void setPetsInternal(Set<Pet> pets) {
384	        this.pets = pets;
385	    }
386	
387	    public List<Pet> getPets() {
388	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
389	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
390	        return Collections.unmodifiableList(sortedPets);
391	    }
392	
393	    public void setPets(List<Pet> pets) {
394	        this.pets = new HashSet<>(pets);
395	    }
396	
397	    public void addPet(Pet pet) {
398	        getPetsInternal().add(pet);
399	        pet.setOwner(this);
400	    }
401	
402	    /**
403	     * Return the Pet with the given name, or null if none found for this Owner.
404	     *
405	     * @param name to test
406	     * @return true if pet name is already in use
407	     */
408	    public Pet getPet(String name) {
409	        return getPet(name, false);
410	    }
411	
412	    /**
413	     * Return the Pet with the given name, or null if none found for this Owner.
414	     *
415	     * @param name to test
416	     * @return true if pet name is already in use
417	     */
418	    public Pet getPet(String name, boolean ignoreNew) {
419	        name = name.toLowerCase();
420	        for (Pet pet : getPetsInternal()) {
421	            if (!ignoreNew || !pet.isNew()) {
422	                String compName = pet.getName();
423	                compName = compName.toLowerCase();
424	                if (compName.equals(name)) {
425	                    return pet;
426	                }
427	            }
428	        }
429	        return null;
430	    }
431	
432	    public Pet getPet(Integer petId) {
433	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
434	    }
435	
436	    @Override
437	    public String toString() {
438	        return new ToStringCreator(this)
439	
440	            .append("id", this.getId())
441	            .append("new", this.isNew())
442	            .append("lastName", this.getLastName())
443	            .append("firstName", this.getFirstName())
444	            .append("address", this.address)
445	            .append("city", this.city)
446	            .append("telephone", this.telephone)
447	            .append("email", this.email)
448	            .toString();
449	    }
450	}
